(()=>{const runtime=document.currentScript.dataset.runtime;let attempts=0;function load(){const script=document.createElement('script');script.src=runtime+(attempts?'?retry='+attempts:'');attempts++;script.onerror=()=>{script.remove();if(attempts<3)setTimeout(load,500*attempts);else{const status=document.createElement('div');status.className='notice';status.setAttribute('role','alert');status.textContent='Portal files could not load. ';const button=document.createElement('button');button.textContent='RETRY CONNECTION';button.onclick=()=>{attempts=0;status.remove();load();};status.append(button);document.querySelector('main')?.prepend(status);}};document.body.append(script);}load();})();
